// Small N: a sorted array is competitive and much simpler than a heap
class SimplePq {
  constructor() { this.a = []; }            // sorted ascending by priority
  push(item) {
    const i = binarySearch(this.a, item.priority);
    this.a.splice(i, 0, item);              // O(n) per insert - fine for small N
  }
  pop() { return this.a.shift(); }          // O(n) but V8's shift is heavily optimised
}

// Large N or frequent priority changes: use a heap library with an index map
// (decrease-key is essential for a Dijkstra-style frontier)
import { PriorityQueue } from 'js-priority-queue';
const pq = new PriorityQueue((a, b) => a.priority - b.priority);   // min-heap
